import type { Context } from '@netlify/edge-functions';
// Generated by scripts/deploy.sh (gitignored). Holds only a SHA-256 hex of "user:pass".
import { AUTH_HASH } from '../edge-lib/auth_hash.ts';

// Credentials are baked into this deploy as a SHA-256 hash (scripts/deploy.sh).
// There is deliberately no env-var fallback: env vars on this account are
// team-scoped, so one site's credential would unlock the other. A missing or
// malformed hash must fail closed (deny everyone).
const MAX_HEADER_LENGTH = 4096;

const encoder = new TextEncoder();

function constantTimeEquals(a: Uint8Array, b: Uint8Array): boolean {
  const maxLength = Math.max(a.length, b.length);
  let mismatch = 0;
  for (let i = 0; i < maxLength; i += 1) {
    mismatch |= (a[i] ?? 0) ^ (b[i] ?? 0);
  }
  mismatch |= a.length ^ b.length;
  return mismatch === 0;
}

export default async (request: Request, context: Context) => {
  const pathname = new URL(request.url).pathname;
  if (pathname === '/.netlify' || pathname.startsWith('/.netlify/')) {
    return await context.next();
  }

  const unauthorized = () =>
    new Response('Unauthorized', {
      status: 401,
      headers: { 'WWW-Authenticate': 'Basic realm="Traffic estimates"' },
    });

  const bakedHash = typeof AUTH_HASH === 'string' && /^[0-9a-f]{64}$/.test(AUTH_HASH) ? AUTH_HASH : '';
  if (!bakedHash) return unauthorized();

  const authHeader = request.headers.get('Authorization');
  if (authHeader && authHeader.length <= MAX_HEADER_LENGTH) {
    const m = authHeader.match(/^\s*basic\s+(\S+)\s*$/i);
    if (m) {
      try {
        // atob yields a Latin-1 string (one code unit per raw byte). Keep the
        // raw bytes rather than UTF-8-encoding the string again, so non-ASCII
        // passwords hash to the same digest as
        // `printf %s <credentials> | sha256sum` in deploy.sh does.
        const bytes = Uint8Array.from(atob(m[1]), (c) => c.charCodeAt(0));
        const digest = await crypto.subtle.digest('SHA-256', bytes);
        const hex = Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('');
        if (constantTimeEquals(encoder.encode(hex), encoder.encode(bakedHash))) {
          return await context.next();
        }
      } catch {
        // Malformed base64 - treat as unauthorized
      }
    }
  }

  return unauthorized();
};
